def get_components(grid, color):
    components = []
    visited = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color and (r,c) not in visited:
                component = []
                queue = list([(r,c)])  # Use list instead of deque
                visited.add((r,c))
                while queue:
                    cr, cc = queue.pop(0)
                    component.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
                min_r = min(p[0] for p in component)
                min_c = min(p[1] for p in component)
                normalized = sorted([(p[0]-min_r, p[1]-min_c) for p in component])
                components.append(normalized)
    return components

